CREATE TABLE savings_goals (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES local_identity(id), workspace_id TEXT NOT NULL REFERENCES workspaces(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), deleted_at TEXT, name TEXT NOT NULL CHECK(length(trim(name))>0), currency TEXT NOT NULL CHECK(length(currency)=3), target_minor INTEGER NOT NULL CHECK(typeof(target_minor)='integer' AND target_minor>=0 AND target_minor<=999999999999999), target_on TEXT, account_id TEXT REFERENCES accounts(id));
CREATE TABLE savings_entries (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES local_identity(id), workspace_id TEXT NOT NULL REFERENCES workspaces(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), deleted_at TEXT, goal_id TEXT NOT NULL REFERENCES savings_goals(id), amount_minor INTEGER NOT NULL CHECK(typeof(amount_minor)='integer' AND amount_minor!=0 AND amount_minor BETWEEN -999999999999999 AND 999999999999999), occurred_on TEXT NOT NULL, transaction_id TEXT REFERENCES transactions(id), transfer_id TEXT REFERENCES transfers(id), CHECK(transaction_id IS NULL OR transfer_id IS NULL));
CREATE TABLE debts (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES local_identity(id), workspace_id TEXT NOT NULL REFERENCES workspaces(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), deleted_at TEXT, name TEXT NOT NULL CHECK(length(trim(name))>0), currency TEXT NOT NULL CHECK(length(currency)=3), direction TEXT NOT NULL CHECK(direction IN('owing','owed')), principal_minor INTEGER NOT NULL CHECK(typeof(principal_minor)='integer' AND principal_minor>=0 AND principal_minor<=999999999999999), calendar_id TEXT REFERENCES calendar_entries(id));
CREATE TABLE debt_entries (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES local_identity(id), workspace_id TEXT NOT NULL REFERENCES workspaces(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), deleted_at TEXT, debt_id TEXT NOT NULL REFERENCES debts(id), flow TEXT NOT NULL CHECK(flow IN('advance','repay')), principal_minor INTEGER NOT NULL CHECK(typeof(principal_minor)='integer' AND principal_minor>=0 AND principal_minor<=999999999999999), interest_minor INTEGER NOT NULL CHECK(typeof(interest_minor)='integer' AND interest_minor>=0 AND interest_minor<=999999999999999), fee_minor INTEGER NOT NULL CHECK(typeof(fee_minor)='integer' AND fee_minor>=0 AND fee_minor<=999999999999999), occurred_on TEXT NOT NULL, transaction_id TEXT REFERENCES transactions(id), CHECK(principal_minor+interest_minor+fee_minor>0));
CREATE TABLE investment_assets (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES local_identity(id), workspace_id TEXT NOT NULL REFERENCES workspaces(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), deleted_at TEXT, name TEXT NOT NULL CHECK(length(trim(name))>0), currency TEXT NOT NULL CHECK(length(currency)=3));
CREATE TABLE investment_entries (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES local_identity(id), workspace_id TEXT NOT NULL REFERENCES workspaces(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), deleted_at TEXT, asset_id TEXT NOT NULL REFERENCES investment_assets(id), kind TEXT NOT NULL CHECK(kind IN('buy','sell','dividend','distribution','valuation')), quantity_micros INTEGER NOT NULL CHECK(typeof(quantity_micros)='integer' AND quantity_micros>=0 AND quantity_micros<=999999999999999), cash_minor INTEGER NOT NULL CHECK(typeof(cash_minor)='integer' AND cash_minor>=0 AND cash_minor<=999999999999999), fee_minor INTEGER NOT NULL CHECK(typeof(fee_minor)='integer' AND fee_minor>=0 AND fee_minor<=999999999999999), occurred_on TEXT NOT NULL, transaction_id TEXT REFERENCES transactions(id), CHECK((kind IN('buy','sell') AND quantity_micros>0) OR (kind NOT IN('buy','sell') AND quantity_micros=0)));
CREATE INDEX savings_goal_entries ON savings_entries(goal_id,occurred_on);
CREATE INDEX debt_ledger ON debt_entries(debt_id,occurred_on);
CREATE INDEX investment_ledger ON investment_entries(asset_id,occurred_on,created_at,id);
